<template><q-page><div class="page-wrap"><PageHeader title="System settings" subtitle="Configure the demonstration’s reporting defaults and account workspace." eyebrow="Administration"/><div class="content-grid"><q-form class="panel" @submit="save"><h3>Reporting defaults</h3><div class="form-grid"><q-input v-model="settings.organizationName" outlined label="Organization name"/><q-select v-model="settings.timezone" outlined label="Reporting timezone" :options="['Asia/Manila','UTC']"/><q-select v-model="settings.defaultYear" outlined label="Default reporting year" :options="['2026','2025','2024','All years']"/><q-input v-model.number="settings.maxUploadMb" outlined type="number" min="1" label="Evidence file limit (MB)"/><q-input v-model="settings.retention" outlined label="Retention policy" class="span-2" hint="Proposed setting only; no actual retention process runs in this demo."/><q-toggle v-model="settings.notificationsEnabled" label="Record local demo notifications"/><q-toggle :model-value="settings.appearance==='dark'" label="Dark appearance" @update:model-value="v=>settings.appearance=v?'dark':'light'"/></div><q-btn class="q-mt-lg" type="submit" no-caps color="primary" unelevated label="Save settings"/></q-form><aside><section class="panel"><h3>Deployment boundary</h3><p class="muted">This GitHub Pages demonstration stores fictional records in this browser. It has no live email, identity, database, upload, backup or retention service.</p><q-btn flat no-caps color="primary" label="View integration handoff" to="/handoff"/></section><section class="panel"><h3>Reset fictional data</h3><p class="muted">Restore all sample records and sign out. Changes made in this browser will be cleared.</p><q-btn outline no-caps color="negative" label="Reset demonstration" @click="reset"/></section></aside></div></div></q-page></template>
<script setup>import{reactive}from'vue';import{useRouter}from'vue-router';import{useQuasar}from'quasar';import{useDemo}from'../stores/demo.js';import PageHeader from'../components/PageHeader.vue';const store=useDemo(),router=useRouter(),$q=useQuasar(),settings=reactive({...store.state.settings});function save(){Object.assign(store.state.settings,settings);store.audit('Updated settings','settings','Reporting defaults');store.persist();$q.dark.set(settings.appearance==='dark');$q.notify({type:'positive',message:'Settings saved in this demonstration.'})}function reset(){$q.dialog({title:'Reset demonstration?',message:'All fictional edits in this browser will be cleared.',cancel:true}).onOk(()=>{store.reset();router.push('/login')})}</script>
